class Animal:
    def __init__(self, name):
        self.name = name
    def hello(self):
        return f"I am {self.name}"

class Dog(Animal):
    pass

d = Dog("Sharik")
print(d.hello(), isinstance(d, Animal), issubclass(Dog, Animal))

class Animal:
    def __init__(self, name):
        self.name = name
    def voice(self):
        return "unknown sound"

class Dog(Animal):
    def __init__(self, name, breed):
        super().__init__(name)
        self.breed = breed
    def voice(self):
        return "woof"

d = Dog("Sharik", "shepherd")
print(d.name, d.breed, d.voice())

class Animal:
    def voice(self):
        return "..."

class Dog(Animal):
    def voice(self):
        return "woof"

class Cat(Animal):
    def voice(self):
        return "meow"

class Duck:                      # not a subclass, but has voice
    def voice(self):
        return "quack"

for a in [Dog(), Cat(), Duck()]:
    print(a.voice())

