print(D().who())
print([k.__name__ for k in D.__mro__])

from abc import ABC, abstractmethod

class Shape(ABC):
    @abstractmethod
    def area(self): ...

class Sq(Shape):
    def __init__(self, a):
        self.a = a
    def area(self):
        return self.a ** 2

print(Sq(3).area())
Shape()

class Engine:
    def start(self):
        return "engine started"

class Car:
    def __init__(self):
        self.engine = Engine()     # "has a"
    def go(self):
        return self.engine.start() + ", off we go"

print(Car().go())

class Base:
    def __init__(self, x):
        self.x = x
    def __repr__(self):
        return f"{type(self).__name__}({self.x})"

class Child(Base):
    pass

print(Base(1), Child(2))

class DictMixin:
    def to_dict(self):
        return dict(self.__dict__)

class User(DictMixin):
    def __init__(self, name):
        self.name = name

print(User("Anya").to_dict())

from abc import ABC, abstractmethod

class Shape(ABC):
    @abstractmethod
    def area(self): ...
    def __str__(self):
        return f"{type(self).__name__}: {self.area():.1f}"

class Circle(Shape):
    def __init__(self, r):
        self.r = r
    def area(self):
        return 3.14159 * self.r ** 2

class Rect(Shape):
    def __init__(self, w, h):
        self.w, self.h = w, h
    def area(self):
        return self.w * self.h

def get_area(s):
    return s.area()

shapes = [Circle(1), Rect(2, 3)]
for s in sorted(shapes, key=get_area, reverse=True):
    print(s)
print(sum(s.area() for s in shapes))

